// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface ITokenFactory {
    function createToken(string memory name_, string memory symbol_, uint256 initialSupply, address owner_) external returns (address);
}

contract StakingManager is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    enum Phase { Rest, Staking, Claiming }

    struct Cycle {
        Phase phase;
        uint256 startTimestamp;
        uint256 stakingEnd;
        uint256 claimEnd;
        address rewardToken;
        address stakedToken;
        uint256 totalStaked;
        address tokenVersionAddress;
    }

    mapping(uint256 => Cycle) public cycles;
    uint256 public currentCycleId;

    // ✅ default durations (in seconds)
    // uint256 public restDuration = 0 days;
    // uint256 public stakingDuration = 48 hours;
    // uint256 public claimDuration = 48 hours;

    uint256 public restDuration = 0;
    uint256 public stakingDuration =120;
    uint256 public claimDuration = 120;

    // cycleId => user => amount
    mapping(uint256 => mapping(address => uint256)) public stakes;

    ITokenFactory public factory;

    event CycleCreated(uint256 indexed cycleId, uint256 start, uint256 stakeEnd, uint256 claimEnd, address stakedToken);
    event Staked(uint256 indexed cycleId, address indexed user, uint256 amount);
    event Claimed(uint256 indexed cycleId, address indexed user, uint256 stakeAmount, uint256 rewardAmount);
    event Forfeited(uint256 indexed cycleId, address indexed user, uint256 amount);
    event PhaseUpdated(uint256 indexed cycleId, Phase newPhase);
    event Finalized(uint256 indexed cycleId, address tokenAddress, string name, string symbol, uint256 initialSupply);

    constructor(address factoryAddress) Ownable(msg.sender) {
        require(factoryAddress != address(0), "zero factory");
        factory = ITokenFactory(factoryAddress);
        currentCycleId = 0;
    }

    function createCycle(address stakedToken) external  {
        require(stakedToken != address(0), "zero token");

        // If not the very first cycle, ensure previous cycle finished its claim period
        if (currentCycleId > 0) {
            Cycle storage prev = cycles[currentCycleId - 1];
            require(prev.startTimestamp != 0, "prev cycle not found");
            require(block.timestamp >= prev.claimEnd, "previous cycle not ended");
            // require(stakedToken == prev.rewardToken, "must stake previous reward token");
        }

        uint256 startTimestamp = block.timestamp + restDuration;
        uint256 stakeEnd = startTimestamp + stakingDuration;
        uint256 claimEnd = stakeEnd + claimDuration;

        cycles[currentCycleId] = Cycle({
            phase: Phase.Rest,
            startTimestamp: startTimestamp,
            stakingEnd: stakeEnd,
            claimEnd: claimEnd,
            rewardToken: address(0),
            stakedToken: stakedToken,
            totalStaked: 0,
            tokenVersionAddress: address(0)
        });
        emit CycleCreated(currentCycleId, startTimestamp, stakeEnd, claimEnd, stakedToken);
        currentCycleId++;
    }

    function _computePhase(uint256 cycleId) internal view returns (Phase) {
        Cycle storage c = cycles[cycleId];
        uint256 t = block.timestamp;
        if (t < c.startTimestamp) {
            return Phase.Rest;
        } else if (t >= c.startTimestamp && t < c.stakingEnd) {
            return Phase.Staking;
        } else if (t >= c.stakingEnd && t < c.claimEnd) {
            return Phase.Claiming;
        } else {
            return Phase.Rest; // finished
        }
    }

    /// @notice Update stored phase and emit event if changed
    function updatePhase(uint256 cycleId) public {
        Phase newPhase = _computePhase(cycleId);
        Cycle storage c = cycles[cycleId];
        if (c.phase != newPhase) {
            c.phase = newPhase;
            emit PhaseUpdated(cycleId, newPhase);
        }
    }

    function stake(uint256 cycleId, uint256 amount) external nonReentrant {
        require(amount > 0, "zero amount");
        updatePhase(cycleId);
        Cycle storage c = cycles[cycleId];
        require(c.phase == Phase.Staking, "not staking phase");
        IERC20(c.stakedToken).safeTransferFrom(msg.sender, address(this), amount);
        stakes[cycleId][msg.sender] += amount;
        c.totalStaked += amount;
        emit Staked(cycleId, msg.sender, amount);
    }

    /// @notice Finalize cycle: create versioned token (with version suffix) and mint initialSupply to this contract so claims can be paid
    function finalizeCycleAndCreateToken(uint256 cycleId) external nonReentrant returns (address) {
        updatePhase(cycleId);
        Cycle storage c = cycles[cycleId];

        require(c.rewardToken == address(0), "cycle already finalized");
        require(block.timestamp >= c.stakingEnd, "staking not ended");
        require(c.totalStaked > 0, "no staked tokens");

        // build versioned name/symbol, e.g., "CyclexV1" and "CyclexV1"
        string memory baseName = "Cyclex";
        string memory baseSymbol = "Cyclex";

        uint256 initialSupply = c.totalStaked;

        string memory nameWithVersion = string(abi.encodePacked(baseName, "V", _uint2str(cycleId + 1)));

        string memory symbolWithVersion = string(abi.encodePacked(baseSymbol,"V", _uint2str(cycleId + 1)));
        // create token via factory and mint initialSupply to THIS contract so reward tokens are available immediately
        address tokenAddr = factory.createToken(nameWithVersion, symbolWithVersion, initialSupply, address(this));

        c.tokenVersionAddress = tokenAddr;
        c.rewardToken = tokenAddr;

        emit Finalized(cycleId, tokenAddr, nameWithVersion, symbolWithVersion, initialSupply);
        return tokenAddr;
    }

    function claim(uint256 cycleId) external nonReentrant {
        updatePhase(cycleId);
        Cycle storage c = cycles[cycleId];
        require(c.phase == Phase.Claiming, "not claim period");
        uint256 userStake = stakes[cycleId][msg.sender];
        require(userStake > 0, "no stake");
        uint256 total = c.totalStaked;

        uint256 rewardBalance = IERC20(c.rewardToken).balanceOf(address(this));
        uint256 reward = 0;
        if (rewardBalance > 0 && total > 0) {
            reward = (rewardBalance * userStake) / total;
        }

        stakes[cycleId][msg.sender] = 0;
        IERC20(c.stakedToken).safeTransfer(msg.sender, userStake);
        if (reward > 0) {
            IERC20(c.rewardToken).safeTransfer(msg.sender, reward);
        }
        emit Claimed(cycleId, msg.sender, userStake, reward);
    }

    /// ---------- Helper / getters for frontend & tests ----------
    function currentToken() external view returns (address) {
        if (currentCycleId == 0) { return address(0); }
        return cycles[currentCycleId - 1].tokenVersionAddress;
    }

    function currentStakedToken() external view returns (address) {
        if (currentCycleId == 0) { return address(0); }
        return cycles[currentCycleId - 1].stakedToken;
    }

    function getCycle(uint256 cycleId) external view returns (
        uint8 phase,
        uint256 startTimestamp,
        uint256 stakingEnd,
        uint256 claimEnd,
        address rewardToken,
        address stakedToken,
        uint256 totalStaked,
        address tokenVersionAddress
    ) {
        Cycle storage c = cycles[cycleId];
        return (
            uint8(c.phase),
            c.startTimestamp,
            c.stakingEnd,
            c.claimEnd,
            c.rewardToken,
            c.stakedToken,
            c.totalStaked,
            c.tokenVersionAddress
        );
    }

    function getUserStake(uint256 cycleId, address user) external view returns (uint256) {
        return stakes[cycleId][user];
    }

    /// small uint->string helper
    function _uint2str(uint _i) internal pure returns (string memory _uintAsString) {
        if (_i == 0) { return "0"; }
        uint j = _i;
        uint len;
        while (j != 0) { len++; j /= 10; }
        bytes memory bstr = new bytes(len);
        uint k = len;
        j = _i;
        while (j != 0) {
            k = k - 1;
            uint8 temp = uint8(48 + j % 10);
            bstr[k] = bytes1(temp);
            j /= 10;
        }
        return string(bstr);
    }
}
